//! Dataset own-key snapshots retain exact native code units and actual attribute order.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_inherited_keys_exact_native_order_and_raw_projection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;n.setAttributeNS(null,'data-first','one');n.setAttributeNS(null,'data-x\ud800-name','two');n.setAttributeNS(null,'data-x\ufffd-name','three');n.setAttributeNS(null,'data-0','four');n.setAttributeNS(null,'data-','five');var names=[];for(var k in d)names.push(k);var expected=['first','x\ud800Name','x\ufffdName','0',''];if(names.length!==5)throw 'native count';for(var i=0;i<5;i++)if(names[i]!==expected[i])throw 'native order identity';"#);}

#[test]
fn dataset_inherited_keys_prototype_names_without_getters_or_native_aliases(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,hits=0;d.native='value';Object.defineProperty(DOMStringMap.prototype,'extra\ud800',{get:function(){hits++;throw 'getter';},enumerable:true,configurable:true});Object.defineProperty(DOMStringMap.prototype,'scalar',{get:function(){hits++;throw 'getter';},enumerable:true,configurable:true});var names=[];for(var k in d)names.push(k);if(names.length!==3||names[0]!=='native'||names[1]!=='extra\ud800'||names[2]!=='scalar'||hits||Object.keys(d).length!==1||n.getAttribute('data-scalar')!==null)throw 'real prototype enumeration only';"#);}

#[test]
fn dataset_inherited_keys_native_names_shadow_prototype_once(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;d['x\ud800']='native';d.scalar='native';Object.defineProperty(DOMStringMap.prototype,'x\ud800',{value:'author',enumerable:true,configurable:true});Object.defineProperty(DOMStringMap.prototype,'scalar',{value:'author',enumerable:true,configurable:true});var names=[];for(var k in d)names.push(k);if(names.length!==2||names[0]!=='x\ud800'||names[1]!=='scalar'||d['x\ud800']!=='native')throw 'native shadows exact prototype';"#);}

#[test]
fn dataset_inherited_keys_nonenumerable_prototype_names_shadow_ancestors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;d['native\ud800']='value';Object.defineProperty(Object.prototype,'hidden\ud800',{value:1,enumerable:true,configurable:true});Object.defineProperty(Object.prototype,'hidden',{value:1,enumerable:true,configurable:true});Object.defineProperty(DOMStringMap.prototype,'hidden\ud800',{value:2,enumerable:false,configurable:true});Object.defineProperty(DOMStringMap.prototype,'hidden',{value:2,enumerable:false,configurable:true});var names=[];for(var k in d)names.push(k);if(names.length!==1||names[0]!=='native\ud800')throw 'nonenumerable shadows';"#);}

#[test]
fn dataset_inherited_keys_live_removal_and_later_addition(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;d.first='first';d['later\ud800']='later';d.laterScalar='later';Object.defineProperty(DOMStringMap.prototype,'tail\ud800',{value:1,enumerable:true,configurable:true});Object.defineProperty(DOMStringMap.prototype,'tailScalar',{value:1,enumerable:true,configurable:true});var names=[];for(var k in d){names.push(k);if(k==='first'){delete d['later\ud800'];delete d.laterScalar;delete DOMStringMap.prototype['tail\ud800'];delete DOMStringMap.prototype.tailScalar;d.newName='new';DOMStringMap.prototype.newTail=1;}}if(names.length!==1||names[0]!=='first')throw 'live deletion and stable snapshot';"#);}

#[test]
fn dataset_inherited_keys_html_svg_and_empty_native_backing(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"Object.defineProperty(DOMStringMap.prototype,'author\ud800',{value:1,enumerable:true,configurable:true});for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset,names=[];for(var k in d)names.push(k);if(names.length!==1||names[0]!=='author\ud800')throw 'empty native prototype';n.setAttributeNS(null,'data-x\ud800-b','value');n.setAttributeNS(null,'data-UP\ud800','excluded');names=[];for(var k in d)names.push(k);if(names.length!==2||names[0]!=='x\ud800B'||names[1]!=='author\ud800')throw 'native HTML SVG eligibility';}"#);}

#[test]
fn dataset_inherited_keys_refusal_is_atomic_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;data['x\ud800']='old';var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;for mode in 0..4{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.retained_limit=p.state.retained,2=>p.state.host_work=0,_=>p.state.execution_deadline=Some(Instant::now())};let error=p.runtime.execute("for(var k in data){}",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(["string work","retained","DOM work","computation time"][mode]),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.state.execution_deadline=None;run(&mut d,&mut f,&mut p,r#"var names=[];for(var k in data)names.push(k);if(names.length!==1||names[0]!=='x\ud800'||watch.takeRecords().length)throw 'enumeration recovers';"#);}}

#[test]
fn dataset_inherited_keys_does_not_copy_native_attribute_values(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','{}');Object.defineProperty(DOMStringMap.prototype,'tail',{{value:1,enumerable:true,configurable:true}});"#,"x".repeat(16000)));p.begin_job();p.state.copy_work=128;p.runtime.execute(r#"var names=[];for(var k in data)names.push(k);if(names.length!==2||names[0]!=='x\ud800'||names[1]!=='tail')throw 'native names without value copies';"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();}
